data class UserAccount(val id:String=UUID.randomUUID().toString(),val username:String,val password:String,val role:String,val shop:String="",val phone:String="",val address:String="")
data class SellerProfile(val shop:String,val phone:String,val address:String)
data class Product(val id:String=UUID.randomUUID().toString(),val name:String,val price:Double,val shop:String,val category:String,val area:String,val image:String,val sellerPhone:String,val sellerAddress:String,val sellerId:String="sample",val stock:Int=10)
