data class Order(val id:String=UUID.randomUUID().toString().take(8).uppercase(),val buyerId:String="",val lines:List<CartLine>,val delivery:String,val district:String="",val deliveryAddress:String="",val deliveryLocation:String="",val deliveryFee:Double=0.0,val paymentMethod:String="Cash",val total:Double,val runnerName:String="",val runnerPhone:String="",val createdAt:Long=System.currentTimeMillis(),val deliveredAt:Long?=null)

fun tr(lang:String,ms:String,en:String)=if(lang=="English")en else ms
@Composable fun money(v:Double)=Text("B$%.2f".format(v))
