@OptIn(ExperimentalMaterial3Api::class)
@Composable fun KadaiKuApp(){
    var language by remember{mutableStateOf("Melayu")}
    var accounts by remember{mutableStateOf(listOf<UserAccount>())}
    var currentUser by remember{mutableStateOf<UserAccount?>(null)}
    var rememberedUsername by remember{mutableStateOf("")}
    var rememberedPassword by remember{mutableStateOf("")}
    var rememberLogin by remember{mutableStateOf(false)}
    var showRegister by remember{mutableStateOf(false)}
    var tab by remember{mutableIntStateOf(0)}
    var products by remember{mutableStateOf(listOf(
        Product(name="Kek Coklat Premium",price=15.0,shop="Dapur Aisyah",category="Makanan",area="Gadong",image="🍰",sellerPhone="+673 7XX XXXX",sellerAddress="Gadong, Brunei-Muara",sellerId="sample-aisyah",stock=12),
        Product(name="Perfume Oud",price=20.0,shop="Brunei Fragrance",category="Beauty",area="Kiulap",image="🧴",sellerPhone="+673 8XX XXXX",sellerAddress="Kiulap, Brunei-Muara",sellerId="sample-fragrance",stock=8),
        Product(name="Baju Melayu",price=35.0,shop="Kedai Kita",category="Fashion",area="Bandar",image="👕",sellerPhone="+673 7XX XXXX",sellerAddress="Bandar Seri Begawan",sellerId="sample-kita",stock=10),
        Product(name="Frozen Food Combo",price=12.0,shop="Mama's Frozen",category="Makanan",area="Tutong",image="🥟",sellerPhone="+673 8XX XXXX",sellerAddress="Tutong, Brunei",sellerId="sample-mama",stock=15)
    ))}
    var cart by remember{mutableStateOf(listOf<CartLine>())};var orders by remember{mutableStateOf(listOf<Order>())};var notices by remember{mutableStateOf(listOf<AppNotice>())};var search by remember{mutableStateOf("")};var showSeller by remember{mutableStateOf(false)};var showAdd by remember{mutableStateOf(false)};var selectedProduct by remember{mutableStateOf<Product?>(null)};var selectedSellerId by remember{mutableStateOf<String?>(null)};var historyOrder by remember{mutableStateOf<Order?>(null)};var showSupport by remember{mutableStateOf(false)};var supportX by remember{mutableStateOf(0f)};var supportY by remember{mutableStateOf(0f)}

    if(currentUser==null){if(showRegister){RegisterScreen(language,{language=it},onBack={showRegister=false},onRegister={username,password,role,shop,phone,address->if(accounts.none{it.username.equals(username,true)}){val account=UserAccount(username=username.trim(),password=password,role=role,shop=shop.trim(),phone=phone.trim(),address=address.trim());accounts=accounts+account;currentUser=account;showRegister=false}})}else{LoginScreen(language,{language=it},if(rememberLogin)rememberedUsername else "",if(rememberLogin)rememberedPassword else "",rememberLogin,onLogin={username,password,rememberMe->accounts.firstOrNull{it.username.equals(username.trim(),true)&&it.password==password}?.let{currentUser=it;rememberLogin=rememberMe;if(rememberMe){rememberedUsername=username.trim();rememberedPassword=password}else{rememberedUsername="";rememberedPassword=""}}},onRegister={showRegister=true})};return}

    val user=currentUser!!;val sellerProfile=SellerProfile(user.shop.ifBlank{tr(language,"Kedai Saya","My Shop")},user.phone,user.address);val availableProducts=products.filter{it.stock>0};val filtered=availableProducts.filter{search.isBlank()||it.name.contains(search,true)||it.shop.contains(search,true)||it.category.contains(search,true)};val buyerOrders=orders.filter{it.buyerId==user.id};val sellerNotices=notices.filter{it.target==user.id}
    Box(Modifier.fillMaxSize()){
        Scaffold(containerColor=Color.White,topBar={CenterAlignedTopAppBar(title={Text("KadaiKu 🇧🇳",fontWeight=FontWeight.Bold,color=Color(0xFF0D47A1))})},bottomBar={NavigationBar{listOf(tr(language,"Home","Home"),tr(language,"Cari","Search"),tr(language,"Troli (${cart.sumOf{it.qty}})","Cart (${cart.sumOf{it.qty}})"),tr(language,"Profil","Profile")).forEachIndexed{i,l->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={},label={Text(l)})}}}){pad->
            when(tab){
                0->Home(filtered,search,{search=it},{if(user.role=="Seller")showSeller=true},{p->cart=addCart(cart,p)},{selectedProduct=it},{selectedSellerId=it.sellerId},Modifier.padding(pad),user.role=="Seller",language)
                1->SearchPage(filtered,search,{search=it},{p->cart=addCart(cart,p)},{selectedProduct=it},{selectedSellerId=it.sellerId},Modifier.padding(pad),language)
                2->CartPage(cart,{p->cart=removeOne(cart,p)},{p->cart=addCart(cart,p)},{p->cart=removeItem(cart,p)},checkout={delivery,district,address,location,fee,payment,total->if(cart.isNotEmpty()){val stockOk=cart.all{line->products.firstOrNull{it.id==line.product.id}?.stock?.let{it>=line.qty}==true};if(stockOk){val runner=if(delivery=="Pickup")Pair("","")else assignMarketplaceRunner();val order=Order(buyerId=user.id,lines=cart.map{it.copy()},delivery=delivery,district=district,deliveryAddress=address,deliveryLocation=location,deliveryFee=fee,paymentMethod=payment,total=total,runnerName=runner.first,runnerPhone=runner.second);orders=orders+order;products=products.map{p->val bought=cart.firstOrNull{it.product.id==p.id}?.qty?:0;if(bought>0)p.copy(stock=(p.stock-bought).coerceAtLeast(0))else p};order.lines.groupBy{it.product.sellerId}.forEach{(sellerId,lines)->if(!sellerId.startsWith("sample-"))notices=notices+AppNotice(target=sellerId,title="New order #${order.id}",message=tr(language,"Buyer membeli ${lines.sumOf{it.qty}} item. Sediakan barang untuk pickup runner.","Buyer purchased ${lines.sumOf{it.qty}} item(s). Prepare them for runner pickup."))};if(order.delivery!="Pickup"){val pickupText=order.lines.distinctBy{it.product.sellerId}.joinToString(" • "){"${it.product.shop}: ${it.product.sellerAddress}"};val dest=listOf(order.deliveryAddress,order.deliveryLocation).filter{it.isNotBlank()}.joinToString(" | ");notices=notices+AppNotice(target="runner:${order.runnerName}",title="Pickup job #${order.id}",message="Pickup: $pickupText | Deliver: $dest")};cart=listOf();tab=3}}},m=Modifier.padding(pad),language=language)
                else->ProfilePage(buyerOrders,user,sellerNotices,{if(user.role=="Seller")showSeller=true},{currentUser=null;cart=listOf();tab=0},{orderId->val target=orders.firstOrNull{it.id==orderId};orders=orders.map{o->if(o.id==orderId&&o.deliveredAt==null)o.copy(deliveredAt=System.currentTimeMillis())else o};target?.lines?.map{it.product.sellerId}?.distinct()?.filterNot{it.startsWith("sample-")}?.forEach{sellerId->notices=notices+AppNotice(target=sellerId,title="Order #$orderId completed",message=tr(language,"Order sudah complete dan sudah masuk History Seller.","Order is complete and has been moved to Seller History."))}},{historyOrder=it},Modifier.padding(pad),language,{language=it})
            }
        }
        FloatingActionButton(onClick={showSupport=true},containerColor=Color(0xFF20C56B),contentColor=Color.White,shape=CircleShape,modifier=Modifier.align(Alignment.BottomEnd).padding(16.dp).offset{IntOffset(supportX.roundToInt(),supportY.roundToInt())}.pointerInput(Unit){detectDragGestures{change,dragAmount->change.consume();supportX+=dragAmount.x;supportY+=dragAmount.y}}){Text("💬")}
    }
    selectedProduct?.let{p->ProductDetailSheet(p,{selectedProduct=null},{cart=addCart(cart,p)},{selectedProduct=null;selectedSellerId=p.sellerId},language)}
    selectedSellerId?.let{id->products.firstOrNull{it.sellerId==id}?.let{anchor->SellerStoreSheet(id,products,anchor,{selectedSellerId=null},{cart=addCart(cart,it)},{selectedProduct=it;selectedSellerId=null},language)}}
    historyOrder?.let{o->HistoryDetailSheet(o,{historyOrder=null},language)}
    if(showSupport)CustomerServiceSheet({showSupport=false},language)
    if(showSeller&&user.role=="Seller")SellerSheet({showSeller=false},{showAdd=true},products,orders,sellerProfile,user.id,{id->products=products.filterNot{it.id==id}},language)
    if(showAdd&&user.role=="Seller")AddProductDialog(sellerProfile,{showAdd=false},{name,price,cat,image,stock->products=products+Product(name=name,price=price,shop=sellerProfile.shop.ifBlank{tr(language,"Kedai Saya","My Shop")},category=cat,area=sellerProfile.address,image=image,sellerPhone=sellerProfile.phone,sellerAddress=sellerProfile.address,sellerId=user.id,stock=stock);showAdd=false},language)
}

