}};item{Button(onClick={onRegister(u,p,role,shop,phone,sellerLocation)},modifier=Modifier.fillMaxWidth(),enabled=u.isNotBlank()&&p.length>=4&&(role=="Buyer"||(shop.isNotBlank()&&phone.isNotBlank()&&sellerLocation.isNotBlank()))){Text(tr(language,"Buat Akaun","Create Account"))}};item{TextButton(onClick=onBack,modifier=Modifier.fillMaxWidth()){Text(tr(language,"Kembali ke Login","Back to Login"))}}}}

fun assignMarketplaceRunner():Pair<String,String>{val runners=listOf(Pair("Hakim","+673 7XX 1010"),Pair("Faris","+673 8XX 2020"),Pair("Azim","+673 7XX 3030"),Pair("Rizal","+673 8XX 4040"));return runners.random()}
fun deliveryFeeFor(district:String):Double=when(district){"Brunei-Muara"->3.0;"Tutong"->5.0;"Kuala Belait"->6.0;"Temburong"->8.0;else->3.0}
fun addCart(c:List<CartLine>,p:Product):List<CartLine>{if(p.stock<=0)return c;val x=c.toMutableList();val i=x.indexOfFirst{it.product.id==p.id};if(i>=0){if(x[i].qty<p.stock)x[i]=x[i].copy(qty=x[i].qty+1)}else x.add(CartLine(p,1));return x}
fun removeOne(c:List<CartLine>,p:Product):List<CartLine>{val x=c.toMutableList();val i=x.indexOfFirst{it.product.id==p.id};if(i>=0){if(x[i].qty>1)x[i]=x[i].copy(qty=x[i].qty-1)else x.removeAt(i)};return x}
fun removeItem(c:List<CartLine>,p:Product)=c.filterNot{it.product.id==p.id}
fun sellerOrderValue(order:Order,sellerId:String)=order.lines.filter{it.product.sellerId==sellerId}.sumOf{it.product.price*it.qty}
@Composable fun ProductImage(image:String,modifier:Modifier=Modifier){if(image.startsWith("content://")||image.startsWith("file://")){Image(rememberAsyncImagePainter(Uri.parse(image)),"Product image",modifier,contentScale=ContentScale.Crop)}else Box(modifier.background(Color(0xFFF5F9FF)),contentAlignment=Alignment.Center){Text(image.ifBlank{"🛍️"},style=MaterialTheme.typography.headlineLarge)}}

