@Composable fun ProductList(ps:List<Product>,add:(Product)->Unit,view:(Product)->Unit,openSeller:(Product)->Unit,language:String){LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp)){items(ps){p->ColorfulProductCard(p,add,view,openSeller,language=language)}}}

@Composable fun CartPage(c:List<CartLine>,minus:(Product)->Unit,plus:(Product)->Unit,remove:(Product)->Unit,checkout:(String,String,String,String,Double,String,Double)->Unit,m:Modifier,language:String){var delivery by remember{mutableStateOf("Delivery")};var district by remember{mutableStateOf("Brunei-Muara")};var address by remember{mutableStateOf("")};var location by remember{mutableStateOf("")};var payment by remember{mutableStateOf("Cash")};val subtotal=c.sumOf{it.product.price*it.qty};val fee=if(c.isEmpty()||delivery=="Pickup")0.0 else deliveryFeeFor(district);Column(m.padding(16.dp)){Text(tr(language,"Troli","Cart"),style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);if(c.isEmpty())Text(tr(language,"Troli masih kosong","Cart is empty"))else{LazyColumn(Modifier.weight(1f)){items(c){x->Card(Modifier.fillMaxWidth().padding(vertical=4.dp)){Row(Modifier.padding(10.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(x.product.name,fontWeight=FontWeight.Bold);Text("${tr(language,"Kuantiti","Qty")}: ${x.qty}")};TextButton({remove(x.product)}){Text(tr(language,"Buang","Remove"))};TextButton({minus(x.product)}){Text("−")};TextButton({plus(x.product)},enabled=x.qty<x.product.stock){Text("+")}}}}};Row{FilterChip(delivery=="Delivery",{delivery="Delivery"},{Text("Delivery")});Spacer(Modifier.width(8.dp));FilterChip(delivery=="Pickup",{delivery="Pickup"},{Text("Pickup")})};if(delivery=="Delivery"){Text(tr(language,"Pilih daerah delivery","Choose delivery district"),fontWeight=FontWeight.Bold);listOf("Brunei-Muara","Tutong","Kuala Belait","Temburong").forEach{d->FilterChip(district==d,{district=d},{Text(d)})};OutlinedTextField(address,{address=it},label={Text(tr(language,"Alamat delivery buyer","Buyer delivery address"))},modifier=Modifier.fillMaxWidth());OutlinedTextField(location,{location=it},label={Text(tr(language,"Share location / Maps link / coordinates","Share location / Maps link / coordinates"))},modifier=Modifier.fillMaxWidth())};Text(tr(language,"Pembayaran","Payment"),fontWeight=FontWeight.Bold);Row{FilterChip(payment=="Cash",{payment="Cash"},{Text("Cash")});Spacer(Modifier.width(8.dp));FilterChip(payment=="Transfer",{payment="Transfer"},{Text("Transfer")})};Text("${tr(language,"Jumlah","Total")}: B$%.2f".format(subtotal+fee),fontWeight=FontWeight.Bold);Button(onClick={checkout(delivery,if(delivery=="Pickup")"Pickup"else district,if(delivery=="Pickup")""else address,if(delivery=="Pickup")""else location,fee,payment,subtotal+fee)},modifier=Modifier.fillMaxWidth(),enabled=delivery=="Pickup"||address.isNotBlank()||location.isNotBlank()){Text(tr(language,"Buat Pesanan","Place Order"))}}}}

@Composable fun ProfilePage(orders:List<Order>,user:UserAccount,notices:List<AppNotice>,seller:()->Unit,logout:()->Unit,markDelivered:(String)->Unit,openHistory:(Order)->Unit,m:Modifier,language:String,onLanguage:(String)->Unit){val active=orders.filter{it.deliveredAt==null};val history=orders.filter{it.deliveredAt!=null};LazyColumn(m.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text(tr(language,"Akaun","Account"),style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("👤 ${user.username}");LanguageChooser(language,onLanguage)};if(user.role=="Seller")item{Button(seller,Modifier.fillMaxWidth()){Text(tr(language,"🏪 Seller Dashboard","🏪 Seller Dashboard"))}};if(user.role=="Seller")items(notices.reversed()){n->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(10.dp)){Text(n.title,fontWeight=FontWeight.Bold);Text(n.message)}}};item{OutlinedButton(logout,Modifier.fillMaxWidth()){Text("Logout")}};item{Text(tr(language,"Pesanan Aktif","Active Orders"),fontWeight=FontWeight.Bold)};items(active.reversed()){o->LiveOrderCard(o,{markDelivered(o.id)},language)};item{Text(tr(language,"History Delivery","Delivery History"),fontWeight=FontWeight.Bold)};items(history.reversed()){o->Box(Modifier.clickable{openHistory(o)}){DeliveredOrderCard(o,language)}}}}
@Composable fun LiveOrderCard(order:Order,onDelivered:()->Unit,language:String){var stage by remember(order.id){mutableIntStateOf(0)};val stages=if(order.delivery=="Pickup")listOf(tr(language,"Order diterima","Order received"),tr(language,"Sedang disediakan","Preparing"),tr(language,"Sedia untuk pickup","Ready for pickup"),tr(language,"Selesai","Complete"))else listOf(tr(language,"Order diterima","Order received"),tr(language,"Seller menyiapkan barang","Seller preparing items"),tr(language,"Runner collect semua seller","Runner collecting from sellers"),tr(language,"Dalam perjalanan","On the way"),tr(language,"Sampai","Delivered"));LaunchedEffect(order.id){while(stage<stages.lastIndex){delay(7000);stage++};if(order.deliveredAt==null)onDelivered()};Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("#${order.id}",fontWeight=FontWeight.Bold);Text(stages[stage]);Text("B$%.2f".format(order.total));if(order.deliveryLocation.isNotBlank())Text("📍 ${order.deliveryLocation}")}}}
@Composable fun DeliveredOrderCard(order:Order,language:String){Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("#${order.id}",fontWeight=FontWeight.Bold);Text(if(order.delivery=="Pickup")tr(language,"✅ Pickup selesai","✅ Pickup complete")else tr(language,"✅ Delivery sampai","✅ Delivered"));Text("B$%.2f".format(order.total))}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable fun HistoryDetailSheet(order:Order,onClose:()->Unit,language:String){ModalBottomSheet(onDismissRequest=onClose){Column(Modifier.padding(20.dp)){Text(tr(language,"Detail History","History Details"),style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);order.lines.forEach{Text("• ${it.product.name} × ${it.qty}")};if(order.deliveryLocation.isNotBlank())Text("📍 ${order.deliveryLocation}")}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable fun CustomerServiceSheet(onClose:()->Unit,language:String){ModalBottomSheet(onDismissRequest=onClose){Column(Modifier.padding(24.dp)){Text("💬 KadaiKu Customer Service",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text(tr(language,"Ada masalah dengan order, seller atau delivery? Hubungi customer service KadaiKu.","Having an issue with an order, seller or delivery? Contact KadaiKu customer service."));Text("📞 +673 7XX XXXX")}}}

fun startOfWeek(now:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=now;set(Calendar.DAY_OF_WEEK,firstDayOfWeek);set(Calendar.HOUR_OF_DAY,0);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};return c.timeInMillis}
fun startOfMonth(now:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=now;set(Calendar.DAY_OF_MONTH,1);set(Calendar.HOUR_OF_DAY,0);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};return c.timeInMillis}
fun startOfYear(now:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=now;set(Calendar.DAY_OF_YEAR,1);set(Calendar.HOUR_OF_DAY,0);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};return c.timeInMillis}
@OptIn(ExperimentalMaterial3Api::class) @Composable fun SellerSheet(onClose:()->Unit,onAdd:()->Unit,products:List<Product>,orders:List<Order>,profile:SellerProfile,sellerId:String,onDelete:(String)->Unit,language:String){val sellerOrders=orders.filter{o->o.lines.any{it.product.sellerId==sellerId}};val active=sellerOrders.filter{it.deliveredAt==null};val history=sellerOrders.filter{it.deliveredAt!=null};ModalBottomSheet(onDismissRequest=onClose){LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("${profile.shop} Dashboard",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text("📞 ${profile.phone}");Text("📍 ${profile.address}")};item{Button(onAdd,Modifier.fillMaxWidth()){Text(tr(language,"+ Tambah Produk","+ Add Product"))}};item{Text(tr(language,"Produk saya / Stok","My Products / Stock"),fontWeight=FontWeight.Bold)};items(products.filter{it.sellerId==sellerId}){p->Card(Modifier.fillMaxWidth()){Row(Modifier.padding(10.dp)){Column(Modifier.weight(1f)){Text(p.name);Text("${tr(language,"Stok","Stock")}: ${p.stock}")};TextButton({onDelete(p.id)}){Text(tr(language,"Padam","Delete"))}}}};item{Text(tr(language,"Order Aktif","Active Orders"),fontWeight=FontWeight.Bold)};items(active){o->Text("#${o.id} • B$%.2f".format(sellerOrderValue(o,sellerId)))};item{Text(tr(language,"History Seller","Seller History"),fontWeight=FontWeight.Bold)};items(history){o->Text("#${o.id} • ✅ ${tr(language,"Selesai","Complete")}")}}}}
@Composable fun StatCard(label:String,count:Int,sales:Double,m:Modifier=Modifier){Card(m){Column(Modifier.padding(10.dp)){Text(label);Text("$count");Text("B$%.2f".format(sales))}}}
@Composable fun AddProductDialog(sellerProfile:SellerProfile,onDismiss:()->Unit,onSave:(String,Double,String,String,Int)->Unit,language:String){var n by remember{mutableStateOf("")};var pr by remember{mutableStateOf("")};var cat by remember{mutableStateOf("Makanan")};var stock by remember{mutableStateOf("")};var imageUri by remember{mutableStateOf("")};val launcher=rememberLauncherForActivityResult(ActivityResultContracts.GetContent()){uri:Uri?->imageUri=uri?.toString().orEmpty()};AlertDialog(onDismissRequest=onDismiss,title={Text(tr(language,"Tambah Produk","Add Product"))},text={Column{OutlinedButton({launcher.launch("image/*")},Modifier.fillMaxWidth()){Text(tr(language,"Pilih gambar dari Gallery","Choose image from Gallery"))};OutlinedTextField(n,{n=it},label={Text(tr(language,"Nama produk","Product name"))});OutlinedTextField(pr,{pr=it},label={Text(tr(language,"Harga B$","Price B$"))});OutlinedTextField(stock,{stock=it.filter{ch->ch.isDigit()}},label={Text(tr(language,"Jumlah stok","Stock quantity"))});OutlinedTextField(cat,{cat=it},label={Text(tr(language,"Kategori","Category"))});Text("📍 ${sellerProfile.address}")}},confirmButton={Button(enabled=n.isNotBlank()&&pr.toDoubleOrNull()!=null&&stock.toIntOrNull()?.let{it>0}==true&&imageUri.isNotBlank(),onClick={onSave(n,pr.toDouble(),cat,imageUri,stock.toInt())}){Text(tr(language,"Simpan","Save"))}},dismissButton={TextButton(onDismiss){Text(tr(language,"Batal","Cancel"))}})}